  return undef if $k==$j;
  my $v=substr($s,$i,$k-$i)+0;
  return undef if $v < -2147483648 || $v > 2147483647;
  return $v; }
sub parse { my ($inp)=@_; my $s=$inp;
  my $p=index($s,'#'); $s=substr($s,0,$p) if $p>=0;
  $p=index($s,'?');    $s=substr($s,0,$p) if $p>=0;
  my ($sc,$ui,$h,$po,$pa)=('','','',-1,'');
  $p=index($s,'://');
  if ($p>=0) { $sc=substr($s,0,$p); my $rest=substr($s,$p+3);
    my $sl=index($rest,'/'); my $auth;
    if ($sl>=0) { $auth=substr($rest,0,$sl); $pa=substr($rest,$sl); } else { $auth=$rest; $pa=''; }
    my $at=index($auth,'@'); my $hp;
