  my @segs = grep { $_ ne '' } split(/\//,$pa,-1);
  return (( ($h ne '' || $pa ne '')?'1':'0'), (schok($sc)?'1':'0'), (hostok($h)?'1':'0'), (($po>=0 && $po<=65535)?'1':'0'), scalar(@segs), @segs); }
