  chomp @out;
  my @pred=predict($c);
  $n++;
  my $a=join("\x01",@out); my $b=join("\x01",@pred);
  if ($a ne $b){ $bad++; print "MISMATCH [".$c."] got[".join('|',@out)."] pred[".join('|',@pred)."]\n" if $bad<=30; }
}
